import{_ as p,a0 as l,w as o,s as c,ao as d,I as a,x as i,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"在 RHEL8 配置静态 IP 地址的不同方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 RHEL8 配置静态 IP 地址的不同方法 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 RHEL8 配置静态 IP 地址的不同方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 RHEL8 配置静态 IP 地址的不同方法 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190901 Different Ways to Configure Static IP Address in RHEL 8","title":"在 RHEL8 配置静态 IP 地址的不同方法","tag":"201909","desc":""},"relativePath":"201909/20190901 Different Ways to Configure Static IP Address in RHEL 8.md","filePath":"[post].md"}'),r={name:"201909/20190901 Different Ways to Configure Static IP Address in RHEL 8.md"};function h(u,s,g,f,k,b){const e=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="在-rhel8-配置静态-ip-地址的不同方法" tabindex="-1">在 RHEL8 配置静态 IP 地址的不同方法 <a class="header-anchor" href="#在-rhel8-配置静态-ip-地址的不同方法" aria-label="Permalink to “在 RHEL8 配置静态 IP 地址的不同方法”">​</a></h1><p>在 Linux 服务器上工作时，在网卡/以太网卡上分配静态 IP 地址是每个 Linux 工程师的常见任务之一。如果一个人在 Linux 服务器上正确配置了静态地址，那么他/她就可以通过网络远程访问它。在本文中，我们将演示在 RHEL 8 服务器网卡上配置静态 IP 地址的不同方法。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201909/25/222737dx94bbl9qbhzlfe4.jpg" alt=""></p><p>以下是在网卡上配置静态IP的方法：</p><ul><li><code>nmcli</code>（命令行工具）</li><li>网络脚本文件（<code>ifcfg-*</code>）</li><li><code>nmtui</code>（基于文本的用户界面）</li></ul><h3 id="使用-nmcli-命令行工具配置静态-ip-地址" tabindex="-1">使用 nmcli 命令行工具配置静态 IP 地址 <a class="header-anchor" href="#使用-nmcli-命令行工具配置静态-ip-地址" aria-label="Permalink to “使用 nmcli 命令行工具配置静态 IP 地址”">​</a></h3><p>每当我们安装 RHEL 8 服务器时，就会自动安装命令行工具 <code>nmcli</code>，它是由网络管理器使用的，可以让我们在以太网卡上配置静态 IP 地址。</p><p>运行下面的 <code>ip addr</code> 命令，列出 RHEL 8 服务器上的以太网卡</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ip addr</span></span></code></pre></div><p>正如我们在上面的命令输出中看到的，我们有两个网卡 <code>enp0s3</code> 和 <code>enp0s8</code>。当前分配给网卡的 IP 地址是通过 DHCP 服务器获得的。</p><p>假设我们希望在第一个网卡 (<code>enp0s3</code>) 上分配静态 IP 地址，具体内容如下:</p><ul><li>IP 地址 = 192.168.1.4</li><li>网络掩码 = 255.255.255.0</li><li>网关 = 192.168.1.1</li><li>DNS = 8.8.8.8</li></ul><p>依次运行以下 <code>nmcli</code> 命令来配置静态 IP，</p><p>使用 <code>nmcli connection</code> 命令列出当前活动的以太网卡，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli connection</span></span>
<span class="line"><span>NAME    UUID                                  TYPE      DEVICE</span></span>
<span class="line"><span>enp0s3  7c1b8444-cb65-440d-9bf6-ea0ad5e60bae  ethernet  enp0s3</span></span>
<span class="line"><span>virbr0  3020c41f-6b21-4d80-a1a6-7c1bd5867e6c  bridge    virbr0</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的 <code>nmcli</code> 给 <code>enp0s3</code> 分配静态 IP。</p><p><strong>命令语法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nmcli connection modify &lt;interface_name&gt; ipv4.address  &lt;ip/prefix&gt;</span></span></code></pre></div><p><strong>注意:</strong> 为了简化语句，在 <code>nmcli</code> 命令中，我们通常用 <code>con</code> 关键字替换 <code>connection</code>，并用 <code>mod</code> 关键字替换 <code>modify</code>。</p><p>将 IPv4 地址 (192.168.1.4) 分配给 <code>enp0s3</code> 网卡上，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.addresses 192.168.1.4/24</span></span></code></pre></div><p>使用下面的 <code>nmcli</code> 命令设置网关，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.gateway 192.168.1.1</span></span></code></pre></div><p>设置手动配置（从 dhcp 到 static），</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.method manual</span></span></code></pre></div><p>设置 DNS 值为 “8.8.8.8”，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con mod enp0s3 ipv4.dns &quot;8.8.8.8&quot;</span></span></code></pre></div><p>要保存上述更改并重新加载，请执行如下 <code>nmcli</code> 命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmcli con up enp0s3</span></span>
<span class="line"><span>Connection successfully activated (D-Bus active path: /org/freedesktop/NetworkManager/ActiveConnection/4)</span></span></code></pre></div><p>以上命令显示网卡 <code>enp0s3</code> 已成功配置。我们使用 <code>nmcli</code> 命令做的那些更改都将永久保存在文件 <code>etc/sysconfig/network-scripts/ifcfg-enp0s3</code> 里。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cat /etc/sysconfig/network-scripts/ifcfg-enp0s3</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/ifcfg-enp0s3-file-rhel8.jpg" alt="ifcfg-enp0s3-file-rhel8"></p><p>要确认 IP 地址是否分配给了 <code>enp0s3</code> 网卡了，请使用以下 IP 命令查看，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]#ip addr show enp0s3</span></span></code></pre></div><h3 id="使用网络脚本文件-ifcfg-手动配置静态-ip-地址" tabindex="-1">使用网络脚本文件（ifcfg-*）手动配置静态 IP 地址 <a class="header-anchor" href="#使用网络脚本文件-ifcfg-手动配置静态-ip-地址" aria-label="Permalink to “使用网络脚本文件（ifcfg-*）手动配置静态 IP 地址”">​</a></h3><p>我们可以使用配置以太网卡的网络脚本或 <code>ifcfg-*</code> 文件来配置以太网卡的静态 IP 地址。假设我们想在第二个以太网卡 <code>enp0s8</code> 上分配静态 IP 地址：</p><ul><li>IP 地址 = 192.168.1.91</li><li>前缀 = 24</li><li>网关 =192.168.1.1</li><li>DNS1 =4.2.2.2</li></ul><p>转到目录 <code>/etc/sysconfig/network-scripts</code>，查找文件 <code>ifcfg-enp0s8</code>，如果它不存在，则使用以下内容创建它，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cd /etc/sysconfig/network-scripts/</span></span>
<span class="line"><span>[root@linuxtechi network-scripts]# vi ifcfg-enp0s8</span></span>
<span class="line"><span>TYPE=&quot;Ethernet&quot;</span></span>
<span class="line"><span>DEVICE=&quot;enp0s8&quot;</span></span>
<span class="line"><span>BOOTPROTO=&quot;static&quot;</span></span>
<span class="line"><span>ONBOOT=&quot;yes&quot;</span></span>
<span class="line"><span>NAME=&quot;enp0s8&quot;</span></span>
<span class="line"><span>IPADDR=&quot;192.168.1.91&quot;</span></span>
<span class="line"><span>PREFIX=&quot;24&quot;</span></span>
<span class="line"><span>GATEWAY=&quot;192.168.1.1&quot;</span></span>
<span class="line"><span>DNS1=&quot;4.2.2.2&quot;</span></span></code></pre></div><p>保存并退出文件，然后重新启动网络管理器服务以使上述更改生效，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi network-scripts]# systemctl restart NetworkManager</span></span></code></pre></div><p>现在使用下面的 <code>ip</code> 命令来验证 IP 地址是否分配给网卡，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ip add show enp0s8</span></span>
<span class="line"><span>3: enp0s8: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc fq_codel state UP group default qlen 1000</span></span>
<span class="line"><span>    link/ether 08:00:27:7c:bb:cb brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 192.168.1.91/24 brd 192.168.1.255 scope global noprefixroute enp0s8</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>    inet6 fe80::a00:27ff:fe7c:bbcb/64 scope link</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上输出内容确认静态 IP 地址已在网卡 <code>enp0s8</code> 上成功配置了。</p><h3 id="使用-nmtui-实用程序配置静态-ip-地址" tabindex="-1">使用 nmtui 实用程序配置静态 IP 地址 <a class="header-anchor" href="#使用-nmtui-实用程序配置静态-ip-地址" aria-label="Permalink to “使用 nmtui 实用程序配置静态 IP 地址”">​</a></h3><p><code>nmtui</code> 是一个基于文本用户界面的，用于控制网络的管理器，当我们执行 <code>nmtui</code> 时，它将打开一个基于文本的用户界面，通过它我们可以添加、修改和删除连接。除此之外，<code>nmtui</code> 还可以用来设置系统的主机名。</p><p>假设我们希望通过以下细节将静态 IP 地址分配给网卡 <code>enp0s3</code> ，</p><ul><li>IP 地址 = 10.20.0.72</li><li>前缀 = 24</li><li>网关 = 10.20.0.1</li><li>DNS1 = 4.2.2.2</li></ul><p>运行 <code>nmtui</code> 并按照屏幕说明操作，示例如下所示，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# nmtui</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/nmtui-rhel8.jpg" alt="nmtui-rhel8"></p><p>选择第一个选项 “Edit a connection”，然后选择接口为 “enp0s3”，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-interface-nmtui-rhel8.jpg" alt="Choose-interface-nmtui-rhel8"></p><p>选择 “Edit”，然后指定 IP 地址、前缀、网关和域名系统服务器 IP，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/set-ip-nmtui-rhel8.jpg" alt="set-ip-nmtui-rhel8"></p><p>选择确定，然后点击回车。在下一个窗口中，选择 “Activate a connection”，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Activate-option-nmtui-rhel8.jpg" alt="Activate-option-nmtui-rhel8"></p><p>选择 “enp0s3”，选择 “Deactivate” 并点击回车，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Deactivate-interface-nmtui-rhel8.jpg" alt="Deactivate-interface-nmtui-rhel8"></p><p>现在选择 “Activate” 并点击回车，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Activate-interface-nmtui-rhel8.jpg" alt="Activate-interface-nmtui-rhel8"></p><p>选择 “Back”，然后选择 “Quit”，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Quit-Option-nmtui-rhel8.jpg" alt="Quit-Option-nmtui-rhel8"></p><p>使用下面的 <code>ip</code> 命令验证 IP 地址是否已分配给接口 <code>enp0s3</code>，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ip add show enp0s3</span></span>
<span class="line"><span>2: enp0s3: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc fq_codel state UP group default qlen 1000</span></span>
<span class="line"><span>    link/ether 08:00:27:53:39:4d brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 10.20.0.72/24 brd 10.20.0.255 scope global noprefixroute enp0s3</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>    inet6 fe80::421d:5abf:58bd:c47e/64 scope link noprefixroute</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上输出内容显示我们已经使用 <code>nmtui</code> 实用程序成功地将静态 IP 地址分配给接口 <code>enp0s3</code>。</p><p>以上就是本教程的全部内容，我们已经介绍了在 RHEL 8 系统上为以太网卡配置 IPv4 地址的三种不同方法。请在下面的评论部分分享反馈和评论。</p><hr>`,68)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/configure-static-ip-address-rhel8/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/configure-static-ip-address-rhel8/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[i("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),n(e,{href:"https://github.com/heguangzhi"},{default:t(()=>[...s[4]||(s[4]=[i("heguangzhi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const P=p(r,[["render",h]]);export{v as __pageData,P as default};
